let NLEAF=1,JK=1,CAMK=1,SENS_K=1,IND=0.85+0.3*Math.random(),GUARD=0,GUARD_T=0;const GEOS={"1":{"body":{"V":"","F":"","n":7692,"L":""},"t2":{"V":"","F":"","n":7692,"L":""},"t3":{"V":"","F":"","n":6478,"L":""},"lm":{"V":"","F":"","n":3764,"L":""},"lf":{"V":"","F":"","n":1676,"L":""}},"4":{"body":{"V":"","F":"","n":11435,"L":""},"t2":{"V":"","F":"","n":11435,"L":""},"t3":{"V":"","F":"","n":8114,"L":""},"lm":{"V":"","F":"","n":4836,"L":""},"lf":{"V":"","F":"","n":2108,"L":""}},"16":{"body":{"V":"","F":"","n":16404,"L":""},"t2":{"V":"","F":"","n":16404,"L":""},"t3":{"V":"","F":"","n":11412,"L":""},"lm":{"V":"","F":"","n":6488,"L":""},"lf":{"V":"","F":"","n":2632,"L":""}}};const FORMTXT={"1":"觸手每一節都是一葉體模型：只有一片葉，每次整顆一起收縮、一起亮；體型 ×1（質量 1）。拖曳旋轉、滾輪縮放。","4":"觸手每一節都是四葉體模型：平常四片葉輪流收縮、輪流亮（省能量的巡航），需要時才同步衝刺；體型 ×1.634（質量 4）。拖曳旋轉、滾輪縮放。","16":"觸手每一節都是十六葉體模型：平常十六片葉輪流收縮、輪流亮，很少同步衝刺；體型 ×2.619（質量 16）。拖曳旋轉、滾輪縮放。"};
// ===== 陶紋水母 — 發光脈動 (p5.js + WebGL) =====
// 參考 Medusae (Ash Weeks) 的做法：觸手用輕量彈簧物理跟隨、泛光與鏡頭光斑、雙層半透明傘、漂浮塵粒。
// 座標：z 朝上。
const C=DATA.C,H=C.Z_TOP-C.Z_RIM,T=4.2;   // 基本脈動週期：2 m 的大型水母脈動很慢（體型越大越慢；漂流時再乘上節奏倍率 → 約 9 秒一下）
let MAT=1,IRI=1;   // IRI：傘緣結構色（本物種假說）開關
   // 材質：1＝數學線稿（math art）、0＝原本的玻璃
let gl,isGL2=false,ext=null,tm=0,paused=false,speed=1,showShell=true,fpsEl;
let yaw=-0.95,pitch=0.32,dist=6200*CAMK,target=[0,0,-1000];

// ---------------- 脈動 ----------------
// 傘的脈動曲線，套用動畫十二法則（像 MG 的彈跳小球）：每一段接縫處速度都是 0 → 不會有頓點
//  預備動作：收縮前先微微張開（c<0）｜緩入緩出：慢起步、中段猛收（smootherstep）、急停
//  hit & hold：收到底多擠一下再停住｜放鬆：長長地拖出去，最後小小回彈一次
const MG={uc:0.34,ant:0.07,hold:0.05};
function sm5(x){x=Math.max(0,Math.min(1,x));return x*x*x*(x*(6*x-15)+10)}
function pulse(u){const uc=MG.uc;
  if(u<uc){const x=u/uc,s1=Math.sin(Math.PI*Math.min(1,x/0.40));return sm5((x-0.22)/0.78)-MG.ant*s1*s1}
  const x=(u-uc)/(1-uc),h=Math.sin(Math.PI*Math.min(1,x/0.16));
  return Math.pow(1-x,2.6)*(1+2.6*x)+MG.hold*h*h-0.10*Math.pow(Math.sin(Math.PI*Math.min(1,x*1.25)),2)*(1-x)}
function pulseAt(x){return pulse(((x%1)+1)%1)}
const S={};
// 後人類世界的外型方案（預覽用開關）：lantern＝傘閉合成浮力燈籠、radial＝外圈觸手放射展開、spire＝口腕絞成中軸、lattice＝傘變成網格骨架
const FORM=Object.assign({lantern:1,radial:1,spire:1,lattice:0},(typeof window!=='undefined'&&window.FORM)||{});
if(typeof location!=='undefined'&&location.hash)for(const k of location.hash.slice(1).split('-'))if(k in FORM)FORM[k]=1;   // 預覽：網址後面加 #lantern-radial-spire-lattice 就能切換
let PH=0;   // 傘部脈動的相位（圈數），和連續時間 tm 分開：脈動可以快慢不一、也可以停下來滑行
const TFLARE=(typeof window!=='undefined'&&window.TFL!==undefined)?window.TFL:0.62,TCONV=(typeof window!=='undefined'&&window.TCV!==undefined)?window.TCV:0.42,TOUT=(typeof window!=='undefined'&&window.TOUT!==undefined)?window.TOUT:0.78;   // 外圈觸手：外張保留比例、往下收攏程度、亮度
const BELLZ=(typeof window!=='undefined'&&window.BZ)||0.72,CONE=(typeof window!=='undefined'&&window.CONE!==undefined)?window.CONE:0.35;   // 參考 Aurelia／Medusae／真實水母：傘寬而扁（高÷直徑≈0.40），收縮時頂部保持圓   // 傘的高度比例、收縮時尖頂程度
function state(){const c=pulseAt(PH)*SWM.amp;S.c=c;const mm=0.82*Math.pow(Math.max(c,0),0.8);S.m=mm*CONE/0.82;S.p=2-mm;   // 菱形（p）照舊；尖頂（m）可調
  const wob=pulseAt(PH-0.045)-c;                     // 延遲的晃動：矮了就變胖、高了就變瘦
  S.sr=(1-0.24*c)*(1-0.10*wob);S.sz=(1+0.05*c+0.22*wob)*Math.pow(S.sr,-0.55)*BELLZ;S.bob=34*pulseAt(PH-0.10)}   // 壓縮伸展：傘收窄時同時拉高（看起來體積不變），張開時變扁
function lp(th,p){return 1/Math.pow(Math.pow(Math.abs(Math.cos(th)),p)+Math.pow(Math.abs(Math.sin(th)),p),1/p)}
function Dp(w){ // 傘殼變形（CPU 版，與著色器相同）
  const zn=(w[2]-C.Z_RIM)/H;let f=S.sr*lp(Math.atan2(w[1],w[0]),S.p);
  if(zn>0){const zc=Math.min(zn,1),rd=Math.pow(Math.max(1-zc*zc,0),0.46),rm=(1-S.m)*rd+S.m*(1-zc);f*=rm/Math.max(rd,1e-3)}
  return [w[0]*f,w[1]*f,C.Z_RIM+S.bob+(w[2]-C.Z_RIM)*S.sz]}
// ---------------- 游動：收縮時往前推，朝游標方向轉 ----------------
const PV=[0,0,100];                         // 轉動中心（傘中央）
let TW=0,FDISP=[0,0,0],CSTEP=0;
let pos=PV.slice(),vel=[0,0,0],qr=[0,0,0,1],cPrev=0,desired=null,ptr=null,jet=0;
const THRUST=430,DRAG=1.15,TURN=0.55;   // 轉身：2 m 的身體轉得慢（rad/s）
// 力學參數（動畫尺度；M 已含附加質量，所以推力／阻力都以 M=1 正規化）
const PHYS={M:1,C_LIN:0.35,C_QUAD:0.04,CDA_AX:1.0,CDA_SIDE:1.7,W_NET:0};
