function topRho(r){r=Math.min(Math.max(r,0),0.999);return Math.asin(Math.pow(r,1/0.92))/(Math.PI/2)}
const GOLD={TN:144,tb:null,tv:null,TK:2,NA:520,NC:420,SEG:4,TH0:-6.5*Math.PI,NV:0,v:null,b:null,NP:377,pd:null,pb:null};
