const GFL={d:[1,0],t:9,D:1,v:0};
function stepGuard(dt){if(GFL.t<GFL.D){GFL.t+=dt;const k=Math.pow(Math.sin(Math.PI*Math.min(1,GFL.t/GFL.D)),2)*GFL.v;SNOW[0]+=GFL.d[0]*k*dt;SNOW[1]+=GFL.d[1]*k*dt}GUARD_T-=dt;const tg=GUARD_T>0?1:0;GUARD+=(tg-GUARD)*(1-Math.exp(-dt*(tg?3:0.8)))}
